def clean(df):
    df = df.copy()
    # remove exact duplicate rows (Order_ID 2006 duplicated)
    df = df.drop_duplicates()
    # fix Category label variants (extra spaces)
    if 'Category' in df.columns:
        df['Category'] = df['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # ensure numeric types
    for c in ['Quantity', 'Price', 'Revenue']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    # enforce Quantity min 1 and Price min 0 (drop invalid negatives)
    if 'Quantity' in df.columns:
        df = df[df['Quantity'] >= 1]
    if 'Price' in df.columns:
        df = df[df['Price'] >= 0]
    # keep only allowed categories after stripping
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    if 'Category' in df.columns:
        df = df[df['Category'].isin(allowed)]
    # fix cross-column violation: Revenue = Quantity * Price
    if 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    # total revenue by category
    if 'Category' not in df.columns or 'Revenue' not in df.columns:
        return {}
    df = df.dropna(subset=['Category'])
    # ensure Revenue is correct if answer called on uncleaned df
    # (clean already recomputes, this is idempotent)
    # group and sum
    g = df.groupby('Category')['Revenue'].sum()
    # convert to plain dict, join multi-column not needed here
    out = {}
    for k, v in g.items():
        if pd.isna(k):
            continue
        # convert numpy types to python
        out[str(k)] = float(v) if isinstance(v, float) else int(v) if not pd.isna(v) else 0
    return out
